<?php
namespace WPKit\SiteDoctor\Scanners; use WPKit\SiteDoctor\{SiteDoctorIssue,SiteDoctorScanner}; if(!defined('ABSPATH'))exit;
final class AccessibilityScanner implements SiteDoctorScanner{public function id():string{return 'accessibility';}public function label():string{return 'Accessibility';}public function scan():array{$o=[];$r=wp_safe_remote_get(home_url('/'),['timeout'=>8]);if(is_wp_error($r))return $o;$h=wp_remote_retrieve_body($r);if(preg_match('/<img(?![^>]*\balt=)[^>]*>/i',$h))$o[]=$this->i('images-without-alt','accessibility','medium','safe','Images without ALT attributes detected','At least one rendered image appears to lack an ALT attribute.','Add meaningful alternative text or an empty ALT for decorative images.');if(!preg_match('/<html[^>]+\blang=["\']/i',$h))$o[]=$this->i('missing-lang','accessibility','low','safe','HTML language attribute not detected','The homepage HTML does not expose a language attribute.','Set the correct site language in WordPress and verify the theme markup.');return $o;}private function i($id,$c,$s,$r,$t,$d,$rec){return new SiteDoctorIssue(['id'=>$id,'category'=>$c,'severity'=>$s,'risk'=>$r,'title'=>$t,'description'=>$d,'recommendation'=>$rec]);}}
